function assessmentNames(): Record<Assessment, string> { return { unreviewed: t("Не проверено", "Unreviewed"), confirmed_by_user: t("Подтверждено", "Confirmed"), hypothesis: t("Гипотеза", "Hypothesis"), refuted_by_user: t("Опровергнуто", "Refuted") }; }
function confidenceNames(): Record<Exclude<Confidence, null>, string> { return { low: t("Низкая", "Low"), medium: t("Средняя", "Medium"), high: t("Высокая", "High") }; }
function attributeNames(): Record<AttributeKind, string> { return { text: t("Текст", "Text"), number: t("Число", "Number"), boolean: t("Да / нет", "Yes / no"), date: t("Дата", "Date"), datetime: t("Дата и время", "Date and time"), url: 'URL', geo: t("Координаты", "Coordinates") }; }
const defaultView: ViewState = { mode: 'graph', selectedId: null, collapsedGroupIds: [], expandedNodeIds: [] };
const errorText = (error: unknown) => error instanceof Error ? error.message : String(error);
const now = () => new Date().toISOString();
const uid = () => crypto.randomUUID();
type Run = (operation: () => Promise<unknown>) => Promise<void>;
type DialogState = { kind: 'project' | 'note' | 'adopt' | 'group' | 'report' | 'settings' | 'types' | 'resources' | 'reports' | 'attach' } | { kind: 'node'; id: ID } | { kind: 'asset'; id: ID } | { kind: 'relation'; id?: ID; source?: ID; target?: ID } | null;

function date(value: string) { return new Date(value).toLocaleString(localeCode()); }
function localDateTime(value: Attribute['value']): string {
  if (typeof value !== 'string' || !value) return '';
  const valueDate = new Date(value);
  if (!Number.isFinite(valueDate.valueOf())) return '';
  const part = (value: number) => String(value).padStart(2, '0');
  return `${valueDate.getFullYear()}-${part(valueDate.getMonth() + 1)}-${part(valueDate.getDate())}T${part(valueDate.getHours())}:${part(valueDate.getMinutes())}`;
}
function activeTrashBatches(project: Project) {
  return project.deletionBatches.filter((batch) => project.nodes.some((node) => node.deletionBatchId === batch.id) || project.relations.some((relation) => relation.deletionBatchId === batch.id));
}
function bytes(value: number) {
  if (value < 1024) return t(`${value} Б`, `${value} B`);
  if (value < 1048576) return t(`${(value / 1024).toFixed(1)} КиБ`, `${(value / 1024).toFixed(1)} KiB`);
  if (value < 1073741824) return t(`${(value / 1048576).toFixed(1)} МиБ`, `${(value / 1048576).toFixed(1)} MiB`);
  return t(`${(value / 1073741824).toFixed(2)} ГиБ`, `${(value / 1073741824).toFixed(2)} GiB`);
}
function attachmentUsage(count: number) { return t(`${count} привязок`, `${count} ${count === 1 ? 'attachment' : 'attachments'}`); }
function typeName(project: Project, node: ProjectNode) { const type = project.nodeTypes.find((type) => type.id === node.typeId); return type ? localizedTypeName(type) : t("Без типа", "Untyped"); }
function attributeValue(attribute: Attribute): string {
  const value = attribute.value;
  if (value === null) return t("Неизвестно", "Unknown");
  if (typeof value === 'boolean') return value ? t("Да", "Yes") : t("Нет", "No");
  if (typeof value !== 'object') return String(value);
  return 'precision' in value ? t(`${value.value} (${value.precision === 'year' ? 'год' : value.precision === 'month' ? 'месяц' : 'день'})`, `${value.value} (${value.precision === 'year' ? 'year' : value.precision === 'month' ? 'month' : 'day'})`) : t(`${value.latitude}, ${value.longitude}${value.accuracyMeters === null ? '' : ` ± ${value.accuracyMeters} м`}`, `${value.latitude}, ${value.longitude}${value.accuracyMeters === null ? '' : ` ± ${value.accuracyMeters} m`}`);
}

function NotePreview({ service, node, revision }: { service: WorkbenchService; node: ProjectNode; revision: number }) {
  const [body, setBody] = useState<string | null>(null), [error, setError] = useState<string | null>(null);
  useEffect(() => {
    let current = true;
    setBody(null); setError(null);
    service.readNote(node.id).then((text) => { if (current) setBody(text); }).catch((reason: unknown) => { if (current) setError(errorText(reason)); });
    return () => { current = false; };
  }, [service, node.id, node.notePath, node.noteHash, revision]);
  if (error) return <p className="tw-error" role="alert">{error}</p>;
  if (body === null) return <p className="tw-muted">{t("Чтение заметки…", "Reading note…")}</p>;
  return body.trim() ? <SafeMarkdown text={body} sourcePath={node.notePath} service={service} /> : <p className="tw-muted">{t("Заметка пока пуста. Откройте её в редакторе Obsidian.", "This note is empty. Open it in the Obsidian editor.")}</p>;
}

function AssetPreview({ asset, service }: { asset: Asset; service: WorkbenchService }) {
  const media = useRef<HTMLMediaElement | null>(null);
  const [failed, setFailed] = useState(false);
  const source = useMemo(() => {
    try { return { url: service.resourceUrl(asset.id), error: null }; }
    catch (error) { return { url: '', error: errorText(error) }; }
  }, [service, asset.id, asset.sha256]);
  useEffect(() => {
    setFailed(false);
    const player = media.current;
    return () => {
      if (player) { player.pause(); player.removeAttribute('src'); player.load(); }
    };
  }, [asset.id]);
  if (source.error) return <p className="tw-error">{source.error}</p>;
  if (failed) return <p className="tw-muted">{t("Формат или кодек не поддерживается. Используйте «Открыть оригинал».", "The format or codec is unsupported. Use “Open original”.")}</p>;
  if (asset.mediaKind === 'audio') return <audio key={asset.id} ref={(element) => { media.current = element; }} src={source.url} controls preload="metadata" onError={() => setFailed(true)} />;
  if (asset.mediaKind === 'video') return <video key={asset.id} ref={(element) => { media.current = element; }} src={source.url} controls preload="metadata" onError={() => setFailed(true)} />;
  if (/^image\/(png|jpeg|gif|webp|bmp|avif)$/i.test(asset.mimeType) && asset.byteSize <= 32 * 1024 * 1024) return <img src={source.url} alt={asset.title} loading="lazy" onError={() => setFailed(true)} />;
  return <div className="tw-file-fallback"><span aria-hidden="true">▤</span><p>{asset.mimeType === 'application/pdf' ? t("PDF откроется в просмотрщике Obsidian.", "The PDF opens in the Obsidian viewer.") : t("Файл хранится в каталоге материалов. Для этого формата встроенный просмотр не используется.", "The file is stored in the materials library. This format has no built-in preview.")}</p></div>;
}

function MediaPanel({ project, node, service, run }: { project: Project; node: ProjectNode; service: WorkbenchService; run: Run }) {
  const attachments = project.attachments.filter((item) => item.nodeId === node.id).sort((a, b) => Number(b.role === 'primary') - Number(a.role === 'primary') || a.sortOrder - b.sortOrder);
  const [selected, setSelected] = useState<string | null>(null);
  const current = attachments.find((item) => item.id === selected) ?? attachments[0];
  const asset = project.assets.find((item) => item.id === current?.assetId && !item.deletedAt);
  useEffect(() => setSelected(null), [node.id]);
  if (!attachments.length) return null;
  return <section className="tw-media-panel" aria-label={t("Материалы документа", "Document materials")}>
    <select aria-label={t("Выбранный материал", "Selected material")} value={current?.id ?? ''} onChange={(event) => setSelected(event.target.value)}>{attachments.map((item) => <option key={item.id} value={item.id}>{item.role === 'primary' ? '★ ' : ''}{project.assets.find((value) => value.id === item.assetId)?.title ?? t("Недоступный материал", "Unavailable material")}</option>)}</select>
    {asset ? <><AssetPreview key={asset.id} asset={asset} service={service} /><div className="tw-row"><span className="tw-muted">{bytes(asset.byteSize)}</span><button onClick={() => void run(() => service.showAsset(asset.id))}>{t("Открыть оригинал", "Open original")}</button>{current?.role !== 'primary' && <button onClick={() => void run(() => service.execute([{ kind: 'attachment.primary', attachmentId: current.id }]))}>{t("Сделать основным", "Set as primary")}</button>}<button className="tw-danger" onClick={() => void run(() => service.execute([{ kind: 'attachment.detach', attachmentId: current.id }]))}>{t("Отвязать", "Detach")}</button></div>{current?.caption && <p>{current.caption}</p>}</> : <p className="tw-error">{t("Материал отсутствует в каталоге.", "The material is missing from the library.")}</p>}
  </section>;
}

type CardData = { title: string; node: ProjectNode; project: Project; service: WorkbenchService; expanded: boolean; collapsed: boolean; members: number; selected: boolean; onToggle: (id: ID) => void; onCollapse: (id: ID) => void; onEdit: (id: ID) => void; run: Run } & Record<string, unknown>;
type GraphNode = Node<CardData, 'traceweave'>;
const GraphCard = memo(function GraphCard({ id, data }: NodeProps<GraphNode>) {
  useSyncExternalStore(subscribeLocale, getLocale, getLocale);
  const type = data.project.nodeTypes.find((item) => item.id === data.node.typeId);
  const far = useStore((state) => state.transform[2] < FAR_ZOOM_THRESHOLD);
  const updateInternals = useUpdateNodeInternals();
  useLayoutEffect(() => { updateInternals(id); }, [id, far, data.expanded, updateInternals]);
  return <article title={far ? `${data.title} · ${type ? localizedTypeName(type) : ''} · ${assessmentNames()[data.node.assessment]}` : undefined} aria-label={data.title} className={`tw-graph-card${far ? ' is-circle' : data.expanded ? ' is-expanded' : ''}${data.selected ? ' is-selected' : ''}${data.node.missing ? ' is-missing' : ''}`} style={{ borderColor: far ? type?.color : undefined, borderTopColor: type?.color ?? 'var(--interactive-accent)' }}>
    <Handle type="target" position={Position.Left} id="target" /><Handle type="source" position={Position.Right} id="source" />
    {far ? <><span className="tw-node-glyph" aria-hidden="true">{nodeGlyph(data.project, data.node)}</span>{data.members > 0 && <button className="tw-circle-members nodrag nopan" aria-label={t(`${data.collapsed ? 'Раскрыть' : 'Свернуть'} группу ${data.title}`, `${data.collapsed ? 'Expand' : 'Collapse'} group ${data.title}`)} onClick={() => data.onCollapse(data.node.id)}>{data.members}</button>}</> : <><div className="tw-card-heading"><span className="tw-node-glyph" aria-hidden="true">{nodeGlyph(data.project, data.node)}</span><div><strong title={data.title}>{data.title}</strong><span>{type ? localizedTypeName(type) : ''} · {assessmentNames()[data.node.assessment]}</span></div></div>
    {data.node.missing && <span className="tw-error">{t("Заметка отсутствует", "Note missing")}</span>}
    <div className="tw-row nodrag nopan"><button title={t("Развернуть карточку", "Expand card")} onClick={() => data.onToggle(data.node.id)}>{data.expanded ? t("Свернуть", "Collapse") : t("Читать", "Read")}</button>{data.members > 0 && <button onClick={() => data.onCollapse(data.node.id)}>{data.collapsed ? t(`Раскрыть группу (${data.members})`, `Expand group (${data.members})`) : t(`Свернуть группу (${data.members})`, `Collapse group (${data.members})`)}</button>}<button aria-label={t(`Редактировать ${data.title}`, `Edit ${data.title}`)} onClick={() => data.onEdit(data.node.id)}>⋯</button></div>
    {data.expanded && <div className="tw-card-body nodrag nopan nowheel"><NotePreview node={data.node} revision={data.project.revision} service={data.service} /><button onClick={() => void data.run(() => data.service.openNote(data.node.id))}>{t("Открыть заметку", "Open note")}</button></div>}</>}
  </article>;
});
type GraphEdgeData = { label: string; offset: number; count: number } & Record<string, unknown>;
type GraphEdge = Edge<GraphEdgeData, 'traceweave'>;
function GraphRelation(props: EdgeProps<GraphEdge>) {
  const { sourceX: sx, sourceY: sy, targetX: tx, targetY: ty } = props;
  const offset = props.data?.offset ?? 0;
  const direction = sx <= tx ? 1 : -1;
  const reach = Math.max(65, Math.abs(tx - sx) * .45);
  const x1 = sx + reach * direction, x2 = tx - reach * direction;
  const path = sx === tx && sy === ty ? `M ${sx} ${sy} C ${sx + 130} ${sy - 130} ${sx - 130} ${sy - 130} ${tx} ${ty}` : `M ${sx} ${sy} C ${x1} ${sy + offset} ${x2} ${ty + offset} ${tx} ${ty}`;
  const labelX = (sx + 3 * x1 + 3 * x2 + tx) / 8, labelY = (sy + 3 * (sy + offset) + 3 * (ty + offset) + ty) / 8;
  return <><BaseEdge id={props.id} path={path} markerStart={props.markerStart} markerEnd={props.markerEnd} style={props.style} interactionWidth={24} />{(props.data?.label || (props.data?.count ?? 0) > 1) && <EdgeLabelRenderer><span className={`tw-edge-label${props.selected ? ' is-selected' : ''}`} style={{ transform: `translate(-50%, -50%) translate(${labelX}px,${labelY}px)` }}>{props.data?.label}{(props.data?.count ?? 0) > 1 ? `${props.data?.label ? ' ' : ''}×${props.data?.count}` : ''}</span></EdgeLabelRenderer>}</>;
}
const nodeTypes = { traceweave: GraphCard };
const edgeTypes = { traceweave: GraphRelation };

function Graph({ project, service, view, setView, visibleIds, run, setDialog, selection, setSelection, setAggregate }: {
  project: Project; service: WorkbenchService; view: ViewState; setView: React.Dispatch<React.SetStateAction<ViewState>>; visibleIds: ReadonlySet<ID>; run: Run; setDialog: (dialog: DialogState) => void; selection: ID[]; setSelection: React.Dispatch<React.SetStateAction<ID[]>>; setAggregate: (ids: ID[]) => void;
}) {
  const locale = useSyncExternalStore(subscribeLocale, getLocale, getLocale);
  const [flow, setFlow] = useState<ReactFlowInstance<GraphNode, GraphEdge> | null>(null);
  const graphElement = useRef<HTMLDivElement>(null), initialFit = useRef(false);
  const projection = useMemo(() => projectGraph(project, view.collapsedGroupIds, visibleIds), [project, view.collapsedGroupIds, visibleIds]);
  const toggle = useCallback((id: ID) => setView((state) => ({ ...state, expandedNodeIds: state.expandedNodeIds.includes(id) ? state.expandedNodeIds.filter((item) => item !== id) : [...state.expandedNodeIds, id] })), [setView]);
  const collapse = useCallback((id: ID) => setView((state) => ({ ...state, collapsedGroupIds: state.collapsedGroupIds.includes(id) ? state.collapsedGroupIds.filter((item) => item !== id) : [...state.collapsedGroupIds, id] })), [setView]);
  const models = useMemo<GraphNode[]>(() => projection.nodes.map((node) => ({ id: node.id, type: 'traceweave', position: canvasPosition(node), zIndex: node.zIndex, data: { title: node.title, node, project, service, expanded: view.expandedNodeIds.includes(node.id), collapsed: view.collapsedGroupIds.includes(node.id), members: project.memberships.filter((item) => item.groupNodeId === node.id).length, selected: view.selectedId === node.id, onToggle: toggle, onCollapse: collapse, onEdit: (id: ID) => setDialog({ kind: 'node', id }), run } })), [projection.nodes, project, service, view.expandedNodeIds, view.collapsedGroupIds, view.selectedId, toggle, collapse, run, setDialog]);
  const [nodes, setNodes] = useState(models);
  useEffect(() => setNodes((current) => {
    const previous = new Map(current.map((node) => [node.id, node]));
    return models.map((node) => {
      const existing = previous.get(node.id);
      return existing ? { ...node, selected: existing.selected, measured: existing.measured } : node;
    });
  }), [models]);
  const edges = useMemo<GraphEdge[]>(() => projection.relations.map((edge) => {
    const relation = edge.relations[0];
    return { id: edge.id, source: edge.source, target: edge.target, sourceHandle: 'source', targetHandle: 'target', type: 'traceweave', selected: view.selectedId === relation.id, ariaLabel: relationLabel(relation) || t("Связь", "Relation"), data: { label: relationLabel(relation), offset: edge.offset, count: edge.relations.length }, markerEnd: relation.directed || relation.bidirectional ? { type: MarkerType.ArrowClosed, width: 17, height: 17 } : undefined, markerStart: relation.bidirectional ? { type: MarkerType.ArrowClosed, width: 17, height: 17 } : undefined, style: { stroke: relation.assessment === 'refuted_by_user' ? 'var(--text-error)' : 'var(--text-muted)', strokeWidth: view.selectedId === relation.id ? 2.5 : 1.6, strokeDasharray: relation.assessment === 'hypothesis' ? '6 4' : undefined } };
  }), [projection.relations, view.selectedId, locale]);
  const connect = (connection: Connection) => { if (connection.source && connection.target && connection.source !== connection.target) setDialog({ kind: 'relation', source: connection.source, target: connection.target }); };
  const selectionChange = useCallback(({ nodes: selected }: { nodes: GraphNode[] }) => setSelection((previous) => stableSelection(previous, selected.map((node) => node.id))), [setSelection]);
  const fitVisible = useCallback(async () => {
    const element = graphElement.current;
    if (!flow || !element) return;
    const target = fitGraphViewport(projection.nodes.map((node) => ({ ...canvasPosition(node), expanded: view.expandedNodeIds.includes(node.id) })), element.clientWidth, element.clientHeight);
    if (target) await flow.setViewport(target);
  }, [flow, projection.nodes, view.expandedNodeIds]);
  useEffect(() => {
    if (!flow || initialFit.current) return;
    initialFit.current = true;
    if (!view.viewport) void run(fitVisible);
  }, [flow, fitVisible, view.viewport, run]);
  return <div className="tw-graph" ref={graphElement}><ReactFlow<GraphNode, GraphEdge> nodes={nodes} edges={edges} nodeTypes={nodeTypes} edgeTypes={edgeTypes} ariaLabelConfig={graphAriaLabels()} onInit={setFlow} onNodesChange={(changes) => setNodes((current) => applyNodeChanges(changes, current))} onNodeDragStop={(_event, _node, moved) => void run(async () => { try { await service.execute([{ kind: 'nodes.move', positions: moved.map((node) => ({ nodeId: node.id, ...documentPosition(node.position) })) }]); } catch (reason) { const confirmed = new Map(models.map((node) => [node.id, node.position])); setNodes((current) => current.map((node) => confirmed.has(node.id) ? { ...node, position: confirmed.get(node.id)! } : node)); throw reason; } })} onConnect={connect}
    onNodeClick={(_event, node) => { setView((current) => ({ ...current, selectedId: node.id })); setAggregate([]); }} onNodeDoubleClick={(_event, node) => toggle(node.id)} onNodeContextMenu={(event, node) => { event.preventDefault(); setView((current) => ({ ...current, selectedId: node.id })); setDialog({ kind: 'node', id: node.id }); }}
    onEdgeClick={(_event, edge) => { const item = projection.relations.find((value) => value.id === edge.id); if (item) { setView((current) => ({ ...current, selectedId: item.relations[0].id })); setAggregate(item.relations.map((relation) => relation.id)); } }} onEdgeDoubleClick={(_event, edge) => { const item = projection.relations.find((value) => value.id === edge.id); if (item?.relations.length === 1) setDialog({ kind: 'relation', id: item.relations[0].id }); }}
    onSelectionChange={selectionChange} onPaneClick={() => { setView((current) => ({ ...current, selectedId: null })); setAggregate([]); }}
    onMoveEnd={(_event, viewport) => setView((current) => ({ ...current, viewport }))} nodeOrigin={[.5, .5]} defaultViewport={view.viewport} minZoom={MIN_GRAPH_ZOOM} maxZoom={MAX_GRAPH_ZOOM} deleteKeyCode={null} multiSelectionKeyCode="Shift" selectionOnDrag panOnDrag={[1, 2]} zoomOnDoubleClick={false} attributionPosition="bottom-left" proOptions={{ hideAttribution: true }}>
    <Background gap={24} size={1} /><Controls showInteractive={false} showFitView={false}><ControlButton className="react-flow__controls-fitview" title={t("Показать весь граф", "Fit graph")} aria-label={t("Показать весь граф", "Fit graph")} onClick={() => void run(fitVisible)}><span aria-hidden="true">⛶</span></ControlButton></Controls><MiniMap<GraphNode> pannable zoomable nodeColor={(node) => node.data.project.nodeTypes.find((type) => type.id === node.data.node.typeId)?.color ?? '#7882a4'} />
  </ReactFlow><div className="tw-graph-legend"><span>{t("Shift + клик: несколько карточек", "Shift + click: select multiple cards")}</span><button onClick={() => void run(fitVisible)}>{t("Показать всё", "Show all")}</button></div></div>;
}

function EvidenceList({ items, project, onSelect }: { items: Evidence[]; project: Project; onSelect: (id: ID) => void }) {
  if (!items.length) return <p className="tw-muted">{t("Источники не указаны.", "No sources specified.")}</p>;
  return <ul className="tw-evidence-list">{items.map((item) => <li key={item.id}><strong>{item.label || t("Источник", "Source")}</strong>{item.sourceKind === 'node' && item.sourceNodeId && <button onClick={() => onSelect(item.sourceNodeId!)}>{project.nodes.find((node) => node.id === item.sourceNodeId)?.title ?? t("Документ в корзине", "Document in trash")}</button>}{item.sourceKind === 'asset' && <span>{project.assets.find((asset) => asset.id === item.assetId)?.title ?? t("Недоступный материал", "Unavailable material")}</span>}{item.sourceKind === 'url' && (safeExternalUrl(item.url) ? <a href={safeExternalUrl(item.url)} rel="noopener noreferrer" target="_blank">{item.url}</a> : <span>{item.url}</span>)}{item.quote && <blockquote>{item.quote}</blockquote>}{item.locator && <small>{item.locator}</small>}{item.note && <p>{item.note}</p>}{item.accessedAt && <small>{t("Дата обращения: ", "Accessed: ")}{date(item.accessedAt)}</small>}</li>)}</ul>;
}

function Inspector({ project, service, selectedId, aggregate, onSelect, run, setDialog, importInput, onClose }: { project: Project; service: WorkbenchService; selectedId: ID | null; aggregate: ID[]; onSelect: (id: ID) => void; run: Run; setDialog: (dialog: DialogState) => void; importInput: () => void; onClose: () => void }) {
  const node = project.nodes.find((item) => item.id === selectedId && !item.deletedAt);
  const relation = project.relations.find((item) => item.id === selectedId && !item.deletedAt);
  if (!node && !relation) return <aside className="tw-inspector tw-inspector-empty"><span className="tw-empty-glyph">◈</span><h3>{t("Исследуйте связи", "Explore connections")}</h3><p>{t("Выберите документ или связь. Перетяните соединитель между карточками, чтобы создать отношение.", "Select a document or relation. Drag a connector between cards to create a relation.")}</p><p className="tw-muted">{t("Тексты и вложения хранятся в обычных папках. Связи и настройки — в скрытой папке .twdata.", "Notes and attachments live in ordinary folders. Relations and settings live in the hidden .twdata folder.")}</p></aside>;
  return <aside className="tw-inspector"><div className="tw-section-heading"><span className="tw-eyebrow">{node ? t("ДОКУМЕНТ", "DOCUMENT") : t("СВЯЗЬ", "RELATION")}</span><button aria-label={t("Закрыть просмотр", "Close inspector")} onClick={onClose}>×</button></div>
    {node ? <><h2>{nodeGlyph(project, node)} {node.title}</h2><div className="tw-tags"><span>{typeName(project, node)}</span><span>{assessmentNames()[node.assessment]}</span>{node.confidence && <span>{t("Уверенность: ", "Confidence: ")}{confidenceNames()[node.confidence]}</span>}</div>
      {node.missing && <p className="tw-error">{t("Файл заметки отсутствует. Выберите «Перепривязать» в редакторе метаданных.", "The note file is missing. Choose another note in the metadata editor to relink it.")}</p>}
      <div className="tw-row"><button className="mod-cta" onClick={() => void run(() => service.openNote(node.id))}>{t("Открыть заметку", "Open note")}</button><button onClick={() => setDialog({ kind: 'node', id: node.id })}>{t("Метаданные", "Metadata")}</button><button onClick={importInput}>{t("Добавить файлы", "Add files")}</button><button onClick={() => setDialog({ kind: 'attach' })}>{t("Из библиотеки", "From library")}</button></div>
      <MediaPanel key={`media:${node.id}`} project={project} node={node} service={service} run={run} /><NotePreview key={`note:${node.id}`} service={service} node={node} revision={project.revision} />
      <h3>{t("Атрибуты", "Attributes")}</h3>{node.attributes.length ? <dl className="tw-attributes">{[...node.attributes].sort((a, b) => a.sortOrder - b.sortOrder).map((item) => <React.Fragment key={item.id}><dt>{item.key}</dt><dd>{attributeValue(item)}</dd></React.Fragment>)}</dl> : <p className="tw-muted">{t("Атрибуты не добавлены.", "No attributes added.")}</p>}
      <h3>{t("Источники", "Sources")}</h3><EvidenceList items={node.evidence} project={project} onSelect={onSelect} />
      <div className="tw-section-heading"><h3>{t("Связи", "Relations")}</h3><button onClick={() => setDialog({ kind: 'relation', source: node.id })}>{t("+ Связь", "+ Relation")}</button></div><ul className="tw-relation-list">{project.relations.filter((item) => !item.deletedAt && (item.sourceNodeId === node.id || item.targetNodeId === node.id)).map((item) => {
        const otherId = item.sourceNodeId === node.id ? item.targetNodeId : item.sourceNodeId;
        return <li key={item.id}><button onClick={() => onSelect(otherId)}>{item.bidirectional ? '↔' : item.directed ? item.sourceNodeId === node.id ? '→' : '←' : '—'} {project.nodes.find((value) => value.id === otherId)?.title ?? t("Удалённый документ", "Deleted document")}</button><button onClick={() => onSelect(item.id)}>{relationLabel(item) || t("Связь", "Relation")}</button></li>;
      })}</ul><p className="tw-path">{node.notePath}</p><small>{t("Обновлено: ", "Updated: ")}{date(node.updatedAt)}</small>
    </> : relation && <>
      {aggregate.length > 1 && <section className="tw-callout"><strong>{t("Проекция группы: ", "Group projection: ")}{aggregate.length}{t(" связей", " relations")}</strong><p>{t("Исходные концы отношений сохранены.", "Original relation endpoints are preserved.")}</p>{aggregate.map((id) => { const item = project.relations.find((value) => value.id === id); return item && <button key={id} onClick={() => onSelect(id)}>{project.nodes.find((value) => value.id === item.sourceNodeId)?.title} → {project.nodes.find((value) => value.id === item.targetNodeId)?.title}: {relationLabel(item) || t("Связь", "Relation")}</button>; })}</section>}
      <h2>{relationLabel(relation) || t("Связь", "Relation")}</h2><div className="tw-relation-endpoints"><button onClick={() => onSelect(relation.sourceNodeId)}>{project.nodes.find((item) => item.id === relation.sourceNodeId)?.title}</button><span>{relation.bidirectional ? '↔' : relation.directed ? '→' : '—'}</span><button onClick={() => onSelect(relation.targetNodeId)}>{project.nodes.find((item) => item.id === relation.targetNodeId)?.title}</button></div>
      <div className="tw-tags"><span>{assessmentNames()[relation.assessment]}</span>{relation.confidence && <span>{confidenceNames()[relation.confidence]}</span>}</div><div className="tw-row"><button onClick={() => setDialog({ kind: 'relation', id: relation.id })}>{t("Изменить связь", "Edit relation")}</button><button className="tw-danger" onClick={() => void run(() => service.execute([{ kind: 'elements.trash', nodeIds: [], relationIds: [relation.id], groupMode: 'group_only' }]))}>{t("В корзину", "Move to trash")}</button></div>
      <SafeMarkdown text={relation.noteMarkdown} /><h3>{t("Источники", "Sources")}</h3><EvidenceList items={relation.evidence} project={project} onSelect={onSelect} /><small>{t("Создано: ", "Created: ")}{date(relation.createdAt)}</small>
    </>}
  </aside>;
}

function Dossier({ project, nodes, selectedId, onSelect }: { project: Project; nodes: ProjectNode[]; selectedId: ID | null; onSelect: (id: ID) => void }) {
  const [layout, setLayout] = useState<'list' | 'cards'>('list'), [sort, setSort] = useState('title');
  const sorted = [...nodes].sort((a, b) => sort === 'updated' ? b.updatedAt.localeCompare(a.updatedAt) : a.title.localeCompare(b.title, localeCode()));
  return <section className="tw-dossier"><div className="tw-section-heading"><span>{nodes.length}{t(" документов", " documents")}</span><div className="tw-row"><select aria-label={t("Сортировка досье", "Dossier sort order")} value={sort} onChange={(event) => setSort(event.target.value)}><option value="title">{t("По названию", "By title")}</option><option value="updated">{t("По обновлению", "By update")}</option></select><button aria-pressed={layout === 'list'} onClick={() => setLayout('list')}>{t("Список", "List")}</button><button aria-pressed={layout === 'cards'} onClick={() => setLayout('cards')}>{t("Карточки", "Cards")}</button></div></div>
    {sorted.length ? <div className={`tw-dossier-${layout}`}>{sorted.map((node) => <button className={`tw-dossier-item${selectedId === node.id ? ' is-selected' : ''}`} key={node.id} onClick={() => onSelect(node.id)}><span className="tw-node-glyph">{nodeGlyph(project, node)}</span><div><strong>{node.title}</strong><span>{typeName(project, node)} · {assessmentNames()[node.assessment]}</span>{layout === 'cards' && <p>{node.attributes.slice(0, 3).map((item) => `${item.key}: ${attributeValue(item)}`).join(' · ') || node.subtitle || node.notePath}</p>}</div><span className="tw-muted">{node.missing ? t("Нет файла", "File missing") : '→'}</span></button>)}</div> : <div className="tw-empty"><h3>{t("Документов по этим условиям нет", "No matching documents")}</h3><p>{t("Измените фильтр или создайте заметку.", "Change the filters or create a note.")}</p></div>}
  </section>;
}

