function ResourceDialog({ service, selectedNodeId, submit }: { service: WorkbenchService; selectedNodeId?: ID; submit: (operation: () => Promise<unknown>) => void }) {
  const [candidates, setCandidates] = useState<ResourceCandidate[] | null>(null), [error, setError] = useState<string | null>(null);
  useEffect(() => { let current = true; service.discoverResources().then((value) => { if (current) setCandidates(value); }).catch((reason: unknown) => { if (current) setError(errorText(reason)); }); return () => { current = false; }; }, [service]);
  return <div><p>{t("Каталог учитывает файлы любого расширения, в том числе невидимые в проводнике Obsidian.", "The library includes every file extension, even files hidden by the Obsidian file explorer.")}</p>{error && <p className="tw-error">{error}</p>}{candidates === null && !error ? <p>{t("Сканирование папки ресурсов…", "Scanning the materials folder…")}</p> : candidates?.length ? <div className="tw-resource-candidates">{candidates.map((item) => <div className="tw-resource-candidate" key={item.path}><div><strong>{item.path}</strong><small>{bytes(item.byteSize)}</small></div>{item.registered ? <span className="tw-muted">{t("В каталоге", "Registered")}</span> : <button onClick={() => submit(() => service.registerResource(item.path, selectedNodeId))}>{t("Зарегистрировать", "Register")}</button>}</div>)}</div> : !error && <p className="tw-muted">{t("В настроенной папке ресурсов файлы не найдены.", "No files found in the configured materials folder.")}</p>}</div>;
}

function TypesEditor({ project, service, submit, draftKey }: { project: Project; service: WorkbenchService; submit: (operation: () => Promise<unknown>) => void; draftKey: string }) {
  const [editing, setEditing] = useDraftField<NodeType>(service, draftKey, "editing", { id: uid(), code: '', name: '', color: '#5e7cea', iconKey: 'file-text', isHidden: false, isSystem: false });
  const [pendingType, setPendingType] = useState<NodeType | null>(null);
  const existing = project.nodeTypes.find((type) => type.id === editing.id);
  const changed = existing ? Object.entries(editing).some(([key, value]) => existing[key as keyof NodeType] !== value) : editing.name !== '' || editing.code !== '' || editing.color !== '#5e7cea' || editing.isHidden || editing.iconKey !== 'file-text';
  const choose = (type: NodeType) => { if (changed) setPendingType(type); else setEditing(type); };
  return <div><div className="tw-type-list">{project.nodeTypes.map((type) => <button key={type.id} onClick={() => choose({ ...type })}><span style={{ background: type.color }} />{localizedTypeName(type)}{type.isHidden ? t(" (скрыт)", " (hidden)") : ''}</button>)}</div><button onClick={() => choose({ id: uid(), code: '', name: '', color: '#5e7cea', iconKey: 'file-text', isHidden: false, isSystem: false })}>{t("+ Новый тип", "+ New type")}</button>{pendingType && <section className="tw-callout" role="alert"><strong>{t("Текущий тип изменён", "Current type has changes")}</strong><p>{t("Отбросить его несохранённые изменения и перейти к другому типу?", "Discard unsaved changes and switch to another type?")}</p><div className="tw-row"><button onClick={() => setPendingType(null)}>{t("Продолжить редактирование", "Continue editing")}</button><button className="tw-danger" onClick={() => { setEditing(pendingType); setPendingType(null); }}>{t("Отбросить и выбрать", "Discard and switch")}</button></div></section>}<form onSubmit={(event) => { event.preventDefault(); submit(() => service.execute([{ kind: 'type.upsert', type: editing }])); }}><Field label={t("Название", "Title")}><input required value={editing.name} onChange={(event) => setEditing({ ...editing, name: event.target.value })} /></Field><Field label={t("Код", "Code")}><input required pattern="[a-z][a-z0-9_-]*" readOnly={!!existing} value={editing.code} onChange={(event) => setEditing({ ...editing, code: event.target.value })} /></Field><Field label={t("Значок типа", "Type icon")}><select value={editing.iconKey} onChange={(event) => setEditing({ ...editing, iconKey: event.target.value })}>{NODE_ICON_KEYS.map((key) => <option key={key} value={key}>{key}</option>)}</select></Field><Field label={t("Цвет", "Color")}><input type="color" value={editing.color} onChange={(event) => setEditing({ ...editing, color: event.target.value })} /></Field><label className="tw-check"><input type="checkbox" checked={editing.isHidden} onChange={(event) => setEditing({ ...editing, isHidden: event.target.checked })} />{t("Скрыть тип в списке создания", "Hide type when creating documents")}</label><div className="tw-dialog-actions"><button type="submit" className="mod-cta">{t("Сохранить тип", "Save type")}</button></div></form></div>;
}

function Dialog({ state, project, service, close, selection, selectedId, ownerDocument }: { state: Exclude<DialogState, null>; project: Project | null; service: WorkbenchService; close: () => void; selection: ID[]; selectedId: ID | null; ownerDocument: Document }) {
  const draftKey = `${project?.id ?? 'vault'}/${state.kind}/${'id' in state ? state.id ?? 'new' : 'new'}/${'source' in state ? state.source ?? '' : ''}/${'target' in state ? state.target ?? '' : ''}`;
  const store = metadataDrafts(service);
  const [busy, setBusy] = useState(false), [error, setError] = useState<string | null>(null), [confirmClose, setConfirmClose] = useState(false);
  const [title, setTitle] = useDraftField(service, draftKey, 'title', ''), [path, setPath] = useDraftField(service, draftKey, 'path', ''), [typeId, setTypeId] = useDraftField(service, draftKey, 'typeId', project?.nodeTypes.find((type) => !type.isHidden && type.code !== 'group')?.id ?? ''), [members, setMembers] = useDraftField<ID[]>(service, draftKey, 'members', selection), [assetId, setAssetId] = useDraftField(service, draftKey, 'assetId', ''), [caption, setCaption] = useDraftField(service, draftKey, 'caption', '');
  const dirty = useSyncExternalStore(store.subscribe, () => store.hasPrefix(draftKey), () => false);
  const persistence = useSyncExternalStore(store.subscribe, () => store.status(project?.id ?? 'vault'), () => store.status(project?.id ?? 'vault'));
  const dirtyRef = useRef(dirty); dirtyRef.current = dirty;
  const requestClose = useCallback(() => { if (dirtyRef.current) setConfirmClose(true); else close(); }, [close]);
  const discard = () => { store.clearPrefix(draftKey); close(); };
  const panel = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const previous = ownerDocument.activeElement as HTMLElement | null;
    const focusable = () => [...(panel.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), a[href]') ?? [])];
    const initialControl = panel.current?.querySelector<HTMLElement>('.tw-dialog-body input:not(:disabled), .tw-dialog-body select:not(:disabled), .tw-dialog-body textarea:not(:disabled)');
    (initialControl ?? focusable()[0])?.focus();
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !busy) { event.stopPropagation(); requestClose(); }
      if (event.key === 'Tab') { const list = focusable(); const first = list[0], last = list.at(-1); if (event.shiftKey && ownerDocument.activeElement === first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && ownerDocument.activeElement === last) { event.preventDefault(); first?.focus(); } }
    };
    const currentPanel = panel.current;
    currentPanel?.addEventListener('keydown', onKey);
    return () => { currentPanel?.removeEventListener('keydown', onKey); previous?.focus(); };
  }, [ownerDocument, requestClose, busy]);
  useEffect(() => { if (confirmClose) panel.current?.querySelector<HTMLElement>('.tw-discard-confirm button')?.focus(); }, [confirmClose]);
  const submit = (operation: () => Promise<unknown>) => {
    if (busy) return;
    setBusy(true); setError(null);
    operation().then(() => { store.clearPrefix(draftKey); close(); }).catch((reason: unknown) => setError(errorText(reason))).finally(() => setBusy(false));
  };
  const titles: Record<NonNullable<DialogState>['kind'], string> = { project: t("Новое исследование", "New research"), note: t("Новый документ", "New document"), adopt: t("Подключить заметку из vault", "Link vault note"), group: t("Создать группу", "Create group"), report: t("Снимок отчёта", "Report snapshot"), settings: t("Исследование", "Research"), node: t("Метаданные документа", "Document metadata"), relation: state.kind === 'relation' && state.id ? t("Изменить связь", "Edit relation") : t("Новая связь", "New relation"), asset: t("Метаданные материала", "Material metadata"), types: t("Типы документов", "Document types"), resources: t("Каталог файлов", "File library"), reports: t("Снимки отчётов", "Report snapshots"), attach: t("Привязать материал", "Attach material") };
  const node = state.kind === 'node' ? project?.nodes.find((item) => item.id === state.id) : undefined;
  const asset = state.kind === 'asset' ? project?.assets.find((item) => item.id === state.id) : undefined;
  return <div className="tw-modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget && !busy) requestClose(); }}><div className="tw-modal" ref={panel} role="dialog" aria-modal="true" aria-label={titles[state.kind]}><div className="tw-modal-heading"><h2>{titles[state.kind]}</h2><button aria-label={t("Закрыть диалог", "Close dialog")} disabled={busy} onClick={requestClose}>×</button></div>{error && <p className="tw-error" role="alert">{error}</p>}{dirty && <p className="tw-draft-notice">{!project ? t("Черновик в памяти до создания исследования.", "Draft stays in memory until the research is created.") : persistence.error ? t("Черновик пока только в памяти: запись в .twdata не завершена.", "Draft is only in memory: saving to .twdata has not completed.") : persistence.pending ? t("Сохранение черновика в .twdata…", "Saving draft to .twdata…") : store.hasRestoredPrefix(draftKey) ? t("Восстановлен черновик метаданных. Проверьте значения и сохраните или отбросьте изменения.", "Metadata draft restored. Review the values, then save or discard changes.") : t("Черновик сохранён в .twdata. Основная модель изменится после сохранения формы.", "Draft saved in .twdata. The main model updates when you save the form.")}</p>}{project && !persistence.hydrated && <p className="tw-draft-notice">{persistence.error ? t("Загрузка черновиков не завершена. Используйте повторную попытку в сообщении об ошибке.", "Draft loading did not complete. Use the retry action in the error message.") : t("Загрузка сохранённых черновиков…", "Loading saved drafts…")}</p>}{project && persistence.error && <div className="tw-callout" role="alert"><p>{persistence.error}</p><button onClick={() => { setError(null); void (persistence.hydrated ? store.flush(project.id) : store.hydrate(service, project.id)).catch((reason: unknown) => setError(errorText(reason))); }}>{persistence.hydrated ? t("Повторить запись черновиков", "Retry saving drafts") : t("Повторить загрузку черновиков", "Retry loading drafts")}</button></div>}<fieldset disabled={busy || confirmClose || !!project && !persistence.hydrated} className="tw-dialog-body">
    {state.kind === 'node' && project && node && <NodeEditor key={node.id} project={project} node={node} service={service} submit={submit} close={requestClose} draftKey={draftKey} />}
    {state.kind === 'relation' && project && <RelationEditor project={project} relation={project.relations.find((item) => item.id === state.id)} source={state.source} target={state.target} service={service} submit={submit} close={requestClose} draftKey={draftKey} />}
    {state.kind === 'asset' && asset && <AssetEditor asset={asset} service={service} submit={submit} close={requestClose} draftKey={draftKey} />}
    {state.kind === 'types' && project && <TypesEditor project={project} service={service} submit={submit} draftKey={draftKey} />}
    {state.kind === 'resources' && <ResourceDialog service={service} selectedNodeId={selectedId && project?.nodes.some((item) => item.id === selectedId) ? selectedId : undefined} submit={submit} />}
    {state.kind === 'reports' && project && <div>{project.snapshots.length ? [...project.snapshots].reverse().map((snapshot) => <div className="tw-resource-candidate" key={snapshot.id}><div><strong>{snapshot.title}</strong><small>{date(snapshot.createdAt)}{t(" · ревизия ", " · revision ")}{snapshot.sourceRevision}</small></div><button onClick={() => submit(() => service.openReport(snapshot.id))}>{t("Открыть", "Open")}</button></div>) : <p className="tw-muted">{t("Снимков пока нет. Создайте отчёт из текущего состояния исследования.", "No snapshots yet. Create a report from the current research state.")}</p>}</div>}
    {state.kind === 'settings' && project && <ProjectSettings project={project} service={service} submit={submit} close={requestClose} draftKey={draftKey} />}
    {['project', 'note', 'adopt', 'group', 'report', 'attach'].includes(state.kind) && <form onSubmit={(event) => { event.preventDefault(); submit(async () => {
      if (state.kind === 'project') await service.createProject(title);
      else if (state.kind === 'note') await service.createNote(title, typeId);
      else if (state.kind === 'adopt') await service.adoptNote(path);
      else if (state.kind === 'group') await service.createGroup(title, members);
      else if (state.kind === 'report') { const snapshot = await service.createReport(title, selection.length ? selection : undefined); await service.openReport(snapshot.id); }
      else if (state.kind === 'attach' && selectedId) await service.execute([{ kind: 'attachment.attach', attachment: { id: uid(), nodeId: selectedId, assetId, role: 'attachment', sortOrder: project?.attachments.filter((item) => item.nodeId === selectedId).length ?? 0, caption: caption || null } }]);
    }); }}>
      {!['adopt', 'attach'].includes(state.kind) && <Field label={t("Название", "Title")}><input autoFocus required value={title} onChange={(event) => setTitle(event.target.value)} /></Field>}
      {state.kind === 'note' && project && <Field label={t("Тип документа", "Document type")}><select value={typeId} onChange={(event) => setTypeId(event.target.value)}>{project.nodeTypes.filter((item) => !item.isHidden && item.code !== 'group').map((item) => <option key={item.id} value={item.id}>{localizedTypeName(item)}</option>)}</select></Field>}
      {state.kind === 'adopt' && <><VaultNotePicker notes={service.listNotes().filter((item) => !project?.nodes.some((node) => node.notePath === item.path))} value={path} onChange={setPath} /><p className="tw-muted">{t("Подключение не копирует заметку и не перемещает её. Редактируйте этот же файл в обычном редакторе Obsidian: изменения будут видны в TraceWeave. Properties и служебные файлы рядом с заметкой не создаются; привязка хранится в .twdata.", "Linking neither copies nor moves the note. Edit the same file in the Obsidian editor: changes appear in TraceWeave. No properties or technical files are added beside the note; the link is stored in .twdata.")}</p></>}
      {state.kind === 'group' && project && <Field label={t("Документы группы", "Group documents")}><div className="tw-checkbox-list">{project.nodes.filter((item) => !item.deletedAt && project.nodeTypes.find((type) => type.id === item.typeId)?.code !== 'group').map((item) => <label className="tw-check" key={item.id}><input type="checkbox" checked={members.includes(item.id)} onChange={(event) => setMembers(event.target.checked ? [...members, item.id] : members.filter((id) => id !== item.id))} />{item.title}</label>)}</div></Field>}
      {state.kind === 'report' && <p className="tw-muted">{selection.length ? t(`Включены выбранные документы: ${selection.length}.`, `Selected documents included: ${selection.length}.`) : t("Включены все активные документы.", "All active documents are included.")}{t(" Снимок сохранит текущие тексты и не изменится при последующем редактировании заметок.", " The snapshot captures the current text and stays unchanged when you edit the original notes.")}</p>}
      {state.kind === 'attach' && project && <><Field label={t("Материал", "Material")}><select autoFocus required value={assetId} onChange={(event) => setAssetId(event.target.value)}><option value="">{t("Выберите файл", "Select a file")}</option>{project.assets.filter((item) => !item.deletedAt && !project.attachments.some((attachment) => attachment.nodeId === selectedId && attachment.assetId === item.id)).map((item) => <option value={item.id} key={item.id}>{item.title} · {bytes(item.byteSize)}</option>)}</select></Field><Field label={t("Подпись привязки", "Attachment caption")}><input value={caption} onChange={(event) => setCaption(event.target.value)} /></Field></>}
      <div className="tw-dialog-actions"><button type="button" onClick={requestClose}>{t("Отмена", "Cancel")}</button><button className="mod-cta" type="submit" disabled={state.kind === 'adopt' && !path}>{state.kind === 'adopt' ? t("Подключить", "Link note") : state.kind === 'attach' ? t("Привязать", "Attach") : t("Создать", "Create")}</button></div>
    </form>}
  </fieldset>{busy && <p role="status" className="tw-muted">{t("Сохранение…", "Saving…")}</p>}{confirmClose && <section className="tw-discard-confirm" role="alertdialog" aria-label={t("Несохранённые изменения", "Unsaved changes")}><h3>{t("Есть несохранённые изменения", "You have unsaved changes")}</h3><p>{t("Закрыть форму и отбросить введённые метаданные?", "Close the form and discard the entered metadata?")}</p><div className="tw-row"><button className="mod-cta" onClick={() => setConfirmClose(false)}>{t("Продолжить редактирование", "Continue editing")}</button><button className="tw-danger" onClick={discard}>{t("Отбросить изменения", "Discard changes")}</button></div></section>}</div></div>;
}

function ProjectSettings({ project, service, submit, close, draftKey }: { project: Project; service: WorkbenchService; submit: (operation: () => Promise<unknown>) => void; close: () => void; draftKey: string }) {
  const [title, setTitle] = useDraftField(service, draftKey, "title", project.title), [description, setDescription] = useDraftField(service, draftKey, "description", project.descriptionMarkdown);
  return <form onSubmit={(event) => { event.preventDefault(); submit(() => service.execute([{ kind: 'project.update', changes: { title, descriptionMarkdown: description } }])); }}><Field label={t("Название", "Title")}><input required value={title} onChange={(event) => setTitle(event.target.value)} /></Field><Field label={t("Описание Markdown", "Markdown description")}><textarea rows={6} value={description} onChange={(event) => setDescription(event.target.value)} /></Field><p className="tw-muted">{t("Ревизия: ", "Revision: ")}{project.revision}{t(". Технические данные: .twdata/projects/", ". Technical data: .twdata/projects/")}{project.id}/</p><div className="tw-dialog-actions"><button type="button" onClick={close}>{t("Отмена", "Cancel")}</button><button type="submit" className="mod-cta">{t("Сохранить", "Save")}</button></div><section className="tw-danger-zone"><h3>{project.status === 'archived' ? t("Исследование в архиве", "Research archived") : t("Архивирование", "Archive research")}</h3><p>{t("Файлы остаются в хранилище. Исследование можно вернуть из архива.", "Files stay in the vault. You can restore the research from the archive.")}</p><button type="button" onClick={() => submit(() => service.execute([{ kind: 'project.update', changes: { status: project.status === 'archived' ? 'active' : 'archived' } }]))}>{project.status === 'archived' ? t("Вернуть из архива", "Restore from archive") : t("Архивировать исследование", "Archive research")}</button></section></form>;
}

function Workbench({ container, service }: { container: HTMLElement; service: WorkbenchService }) {
  useSyncExternalStore(subscribeLocale, getLocale, getLocale);
  const subscribe = useCallback((listener: () => void) => service.subscribe(listener), [service]);
  const getSnapshot = useCallback(() => service.getSnapshot(), [service]);
  const snapshot = useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
  const project = snapshot.project;
  const drafts = metadataDrafts(service);
  const draftStatus = useSyncExternalStore(drafts.subscribe, () => drafts.status(project?.id ?? 'vault'), () => drafts.status(project?.id ?? 'vault'));
  const [view, setView] = useState<ViewState>(defaultView), [viewLoaded, setViewLoaded] = useState(false), [dialog, setDialog] = useState<DialogState>(null), [error, setError] = useState<string | null>(null), [notice, setNotice] = useState(''), [query, setQuery] = useState(''), [typeFilter, setTypeFilter] = useState(''), [assessmentFilter, setAssessmentFilter] = useState(''), [groupFilter, setGroupFilter] = useState(''), [searchIds, setSearchIds] = useState<Set<ID> | null>(null), [searching, setSearching] = useState(false), [selection, setSelection] = useState<ID[]>([]), [aggregate, setAggregate] = useState<ID[]>([]), [compact, setCompact] = useState(false), [narrow, setNarrow] = useState(false), [inspectorOpen, setInspectorOpen] = useState(true);
  const filesInput = useRef<HTMLInputElement>(null), archiveInput = useRef<HTMLInputElement>(null), importTarget = useRef<ID | undefined>(undefined);
  const run = useCallback<Run>(async (operation) => { setError(null); try { await operation(); } catch (reason) { setError(errorText(reason)); } }, []);
  useEffect(() => {
    if (project) void drafts.hydrate(service, project.id).catch(() => { /* The subscribed draft status displays the exact error and retry action. */ });
  }, [drafts, service, project?.id]);
  useEffect(() => {
    const Observer = container.ownerDocument.defaultView?.ResizeObserver;
    if (!Observer) return;
    const observer = new Observer((entries) => { const width = entries[0]?.contentRect.width ?? 1200; setCompact(width < 980); setNarrow(width < 560); });
    observer.observe(container); return () => observer.disconnect();
  }, [container]);
  useEffect(() => {
    let current = true; setDialog(null); setViewLoaded(false); setSelection([]); setAggregate([]); setQuery(''); setSearchIds(null); setTypeFilter(''); setAssessmentFilter(''); setGroupFilter('');
    service.loadView().then((value) => { if (current) { setView({ ...defaultView, ...value }); setViewLoaded(true); } }).catch((reason: unknown) => { if (current) { setError(errorText(reason)); setView(defaultView); setViewLoaded(true); } });
    return () => { current = false; };
  }, [service, project?.id]);
  useEffect(() => {
    if (!viewLoaded || !project) return;
    const window = container.ownerDocument.defaultView;
    const timer = window?.setTimeout(() => { service.saveView(view).catch((reason: unknown) => setError(errorText(reason))); }, 200);
    return () => { if (timer !== undefined) window?.clearTimeout(timer); };
  }, [view, viewLoaded, project?.id, service, container]);
  useEffect(() => {
    let current = true;
    if (!query.trim()) { setSearchIds(null); setSearching(false); return; }
    setSearching(true);
    const window = container.ownerDocument.defaultView;
    const timer = window?.setTimeout(() => { service.search(query).then((hits) => { if (current) { setSearchIds(new Set(hits.map((item) => item.nodeId))); setSearching(false); } }).catch((reason: unknown) => { if (current) { setError(errorText(reason)); setSearchIds(new Set()); setSearching(false); } }); }, 180);
    return () => { current = false; if (timer !== undefined) window?.clearTimeout(timer); };
  }, [query, project?.revision, service, container]);
  const visibleNodes = useMemo(() => project?.nodes.filter((node) => !node.deletedAt && (!typeFilter || node.typeId === typeFilter) && (!assessmentFilter || node.assessment === assessmentFilter) && (!groupFilter || node.id === groupFilter || project.memberships.some((member) => member.groupNodeId === groupFilter && member.memberNodeId === node.id)) && (!searchIds || searchIds.has(node.id))) ?? [], [project, typeFilter, assessmentFilter, groupFilter, searchIds]);
  const visibleIds = useMemo(() => new Set(visibleNodes.map((node) => node.id)), [visibleNodes]);
  const onSelect = useCallback((id: ID) => { setView((current) => ({ ...current, selectedId: id })); setInspectorOpen(true); }, []);
  const openFiles = useCallback((nodeId?: ID) => { importTarget.current = nodeId; filesInput.current?.click(); }, []);
  const closeDialog = useCallback(() => setDialog(null), []);
  const selectedNode = project?.nodes.find((node) => node.id === view.selectedId && !node.deletedAt);
  const selectedIds = selection.length ? selection : selectedNode ? [selectedNode.id] : [];
  return <div className={`tw-obsidian${compact ? ' is-compact' : ''}${narrow ? ' is-narrow' : ''}`} onDragOver={(event) => { if (event.dataTransfer.types.includes('Files')) event.preventDefault(); }} onDrop={(event) => { if (event.dataTransfer.files.length) { event.preventDefault(); void run(() => service.importFiles(Array.from(event.dataTransfer.files), selectedNode?.id)); } }}>
    <header className="tw-header"><div className="tw-brand"><span className="tw-brand-symbol">◈</span><div><strong>TraceWeave</strong><small>{t("Исследования в вашем хранилище", "Research in your vault")}</small></div></div><div className="tw-project-picker"><select aria-label={t("Текущее исследование", "Current research")} value={project?.id ?? ''} disabled={snapshot.busy} onChange={(event) => void run(() => service.openProject(event.target.value))}><option disabled value="">{t("Выберите исследование", "Select research")}</option>{snapshot.projects.map((item) => <option key={item.id} value={item.id}>{item.title}{item.status === 'archived' ? t(" · архив", " · archived") : ''}</option>)}</select><button aria-label={t("Создать исследование", "Create research")} onClick={() => setDialog({ kind: 'project' })}>+</button>{project && <button title={t("Настройки исследования", "Research settings")} onClick={() => setDialog({ kind: 'settings' })}>⋯</button>}</div><div className="tw-history"><button disabled={!snapshot.canUndo || snapshot.busy} onClick={() => void run(() => service.undo())} title={t("Отменить последнюю операцию с метаданными", "Undo last metadata operation")}>↶</button><button disabled={!snapshot.canRedo || snapshot.busy} onClick={() => void run(() => service.redo())} title={t("Повторить операцию с метаданными", "Redo metadata operation")}>↷</button></div></header>
    {(error || snapshot.error) && <div className="tw-banner tw-error" role="alert"><span>{error || snapshot.error}</span><button disabled={snapshot.busy} onClick={() => void run(() => service.recover())}>{t("Проверить восстановление", "Check recovery")}</button>{error && <button aria-label={t("Скрыть ошибку", "Dismiss error")} onClick={() => setError(null)}>×</button>}</div>}
    {project && draftStatus.error && <div className="tw-banner tw-error" role="alert"><span>{t("Не удалось сохранить или восстановить черновики: ", "Could not save or restore drafts: ")}{draftStatus.error}{t(". Введённые значения остаются в памяти.", ". Entered values remain in memory.")}</span><button onClick={() => void run(() => draftStatus.hydrated ? drafts.flush(project.id) : drafts.hydrate(service, project.id))}>{draftStatus.hydrated ? t("Повторить запись черновиков", "Retry saving drafts") : t("Повторить загрузку черновиков", "Retry loading drafts")}</button></div>}
    {notice && <div className="tw-banner" role="status"><span>{notice}</span><button aria-label={t("Скрыть сообщение", "Dismiss message")} onClick={() => setNotice('')}>×</button></div>}
    {snapshot.progress && <div className="tw-progress" role="status"><span>{snapshot.progress.name}: {snapshot.progress.completed} / {snapshot.progress.total}</span><progress value={snapshot.progress.completed} max={snapshot.progress.total || 1} /><button onClick={() => service.cancelImport()}>{t("Отменить импорт", "Cancel import")}</button></div>}
    {project ? <><nav className="tw-navigation" aria-label={t("Представление исследования", "Research view")}>{([['graph', t("Граф", "Graph")], ['dossier', t("Досье", "Dossier")], ['materials', t("Материалы", "Materials")], ['trash', t("Корзина", "Trash")]] as const).map(([mode, label]) => <button key={mode} aria-pressed={view.mode === mode} onClick={() => setView((current) => ({ ...current, mode }))}>{label}{mode === 'materials' && <span>{project.assets.filter((item) => !item.deletedAt).length}</span>}{mode === 'trash' && activeTrashBatches(project).length > 0 && <span>{activeTrashBatches(project).length}</span>}</button>)}<div className="tw-nav-actions"><button disabled={snapshot.busy} title={t("Все активные заметки, связи, вложения и Canvas в обычной папке хранилища", "All active notes, relationships, attachments and Canvas in a regular vault folder")} onClick={() => void run(async () => { await drafts.flush(project.id); const report = await service.exportReadableReport(); setNotice(t(`Отчёт сохранён: ${report.summaryPath}`, `Report saved: ${report.summaryPath}`)); })}>{t("Экспорт отчёта", "Export report")}</button><button onClick={() => setDialog({ kind: 'reports' })}>{t("Снимки", "Snapshots")}</button><button onClick={() => setDialog({ kind: 'report' })}>{t("Снимок отчёта", "Report snapshot")}</button><button onClick={() => void run(async () => { const path = await service.exportProject(); setNotice(t(`Архив сохранён: ${path}`, `Archive saved: ${path}`)); })}>{t("Копия vault ZIP", "Vault backup ZIP")}</button><button onClick={() => void run(async () => { const path = await service.exportTraceWeave(); setNotice(t(`Архив TraceWeave 2.0 сохранён: ${path}`, `TraceWeave 2.0 archive saved: ${path}`)); })}>{t("Архив для TraceWeave", "TraceWeave archive")}</button><button onClick={() => archiveInput.current?.click()}>{t("Импорт ZIP", "Import ZIP")}</button></div></nav>
      {project.status === 'archived' && <div className="tw-banner">{t("Исследование в архиве. Вернуть его можно в настройках исследования.", "Research is archived. Restore it in research settings.")}</div>}
      {(view.mode === 'graph' || view.mode === 'dossier') && <div className="tw-toolbar"><div className="tw-search"><span>⌕</span><input type="search" aria-label={t("Поиск по исследованию", "Search research")} value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t("Поиск по текстам и метаданным", "Search notes and metadata")} />{searching && <small>{t("Поиск…", "Searching…")}</small>}</div><select aria-label={t("Фильтр по типу", "Filter by type")} value={typeFilter} onChange={(event) => setTypeFilter(event.target.value)}><option value="">{t("Все типы", "All types")}</option>{project.nodeTypes.map((type) => <option value={type.id} key={type.id}>{localizedTypeName(type)}</option>)}</select><select aria-label={t("Фильтр по оценке", "Filter by assessment")} value={assessmentFilter} onChange={(event) => setAssessmentFilter(event.target.value)}><option value="">{t("Все оценки", "All assessments")}</option>{Object.entries(assessmentNames()).map(([key, name]) => <option key={key} value={key}>{name}</option>)}</select><select aria-label={t("Фильтр по группе", "Filter by group")} value={groupFilter} onChange={(event) => setGroupFilter(event.target.value)}><option value="">{t("Все группы", "All groups")}</option>{project.nodes.filter((node) => !node.deletedAt && project.nodeTypes.find((type) => type.id === node.typeId)?.code === 'group').map((node) => <option key={node.id} value={node.id}>{node.title}</option>)}</select><button className="mod-cta" onClick={() => setDialog({ kind: 'note' })}>{t("+ Документ", "+ Document")}</button><button onClick={() => setDialog({ kind: 'adopt' })}>{t("Подключить заметку из vault", "Link vault note")}</button><button onClick={() => setDialog({ kind: 'group' })}>{t("Группа", "Group")}</button><button onClick={() => setDialog({ kind: 'types' })}>{t("Типы", "Types")}</button><button aria-pressed={inspectorOpen} onClick={() => setInspectorOpen(!inspectorOpen)}>{t("Просмотр", "Inspector")}</button></div>}
      {selection.length > 1 && view.mode === 'graph' && <div className="tw-selection-bar"><span>{t("Выбрано: ", "Selected: ")}{selection.length}</span><button onClick={() => setDialog({ kind: 'group' })}>{t("Сгруппировать", "Group selection")}</button><button className="tw-danger" onClick={() => void run(() => service.execute([{ kind: 'elements.trash', nodeIds: selection, relationIds: [], groupMode: 'group_only' }]))}>{t("В корзину", "Move to trash")}</button></div>}
      <main className={`tw-workspace${(view.mode === 'graph' || view.mode === 'dossier') && inspectorOpen ? ' with-inspector' : ''}`}>
        {view.mode === 'graph' && viewLoaded && <Graph project={project} service={service} view={view} setView={setView} visibleIds={visibleIds} run={run} setDialog={setDialog} selection={selection} setSelection={setSelection} setAggregate={setAggregate} />}
        {view.mode === 'dossier' && <Dossier project={project} nodes={visibleNodes} selectedId={view.selectedId} onSelect={onSelect} />}
        {view.mode === 'materials' && <Materials project={project} service={service} run={run} setDialog={setDialog} importInput={() => openFiles()} />}
        {view.mode === 'trash' && <Trash project={project} service={service} run={run} />}
        {(view.mode === 'graph' || view.mode === 'dossier') && inspectorOpen && <Inspector project={project} service={service} selectedId={view.selectedId} aggregate={aggregate} onSelect={onSelect} run={run} setDialog={setDialog} importInput={() => openFiles(selectedNode?.id)} onClose={() => setInspectorOpen(false)} />}
      </main><footer className="tw-footer"><span>{draftStatus.pending ? t("Черновик сохраняется…", "Saving draft…") : snapshot.busy ? t("Обработка…", "Processing…") : snapshot.message || t("Метаданные сохранены", "Metadata saved")}{t(" · ревизия ", " · revision ")}{project.revision}</span><span>{visibleNodes.length}{t(" документов · ", " documents · ")}{project.relations.filter((item) => !item.deletedAt).length}{t(" связей", " relations")}</span></footer>
    </> : <main className="tw-welcome"><span className="tw-welcome-glyph">◈</span><h1>{t("Связи между вашими заметками", "Connect your notes")}</h1><p>{t("Создайте исследование или импортируйте архив TraceWeave. Новые заметки и вложения сохраняются в видимых папках Исследования/Заметки и Исследования/Вложения. Подключённые заметки остаются на месте. Служебные данные скрыты в .twdata.", "Create research or import a TraceWeave archive. New notes and attachments are saved in the visible Исследования/Заметки and Исследования/Вложения folders. Linked notes stay in place. Technical data is hidden in .twdata.")}</p><div className="tw-row"><button className="mod-cta" onClick={() => setDialog({ kind: 'project' })}>{t("Создать исследование", "Create research")}</button><button onClick={() => archiveInput.current?.click()}>{t("Импортировать ZIP", "Import ZIP")}</button></div></main>}
    <input hidden ref={filesInput} type="file" multiple onChange={(event) => { const files = Array.from(event.target.files ?? []); event.target.value = ''; if (files.length) void run(() => service.importFiles(files, importTarget.current)); }} /><input hidden ref={archiveInput} type="file" accept=".zip,application/zip" onChange={(event) => { const file = event.target.files?.[0]; event.target.value = ''; if (file) void run(() => service.importArchive(file)); }} />
    {dialog && <Dialog key={`${project?.id ?? 'vault'}/${dialog.kind}/${'id' in dialog ? dialog.id ?? '' : ''}/${'source' in dialog ? dialog.source ?? '' : ''}/${'target' in dialog ? dialog.target ?? '' : ''}`} state={dialog} project={project} service={service} close={closeDialog} selection={selectedIds} selectedId={selectedNode?.id ?? null} ownerDocument={container.ownerDocument} />}
  </div>;
}

export function mountWorkbench(container: HTMLElement, service: WorkbenchService): () => void {
  const root = createRoot(container);
  root.render(<ReactFlowProvider><Workbench container={container} service={service} /></ReactFlowProvider>);
  return () => root.unmount();
}

/** The plugin lifecycle awaits this before releasing its single-writer lease. */
export function flushWorkbenchDrafts(service: WorkbenchService): Promise<void> {
  return metadataDrafts(service).flush();
}
